// Native block facts for the 0.40.0 reservations (internal 132-137). Shared leaf module (no imports) so
// world.js, lighting.js, rails.js, doors-panes.js and shadows.js read one table, and the dispenser, hopper,
// brewing and rail tracks extend behaviour in their own modules. Evidence: fence-rail-reference.json "block"
// records for original ids 158, 154, 117, 27, 28, 157 and shadow-reference.json (regenerated by
// tools/verify-fence-rail.mjs and tools/verify-shadows.mjs).
export const DROPPER = 132, HOPPER = 133, BREWING_STAND = 134, POWERED_RAIL = 135, DETECTOR_RAIL = 136, ACTIVATOR_RAIL = 137;
export const NEW_BLOCK_FIRST = 132, NEW_BLOCK_LAST = 137;
export const isNewBlock = (b) => b >= NEW_BLOCK_FIRST && b <= NEW_BLOCK_LAST;
// BlockRailBase subclasses: no collision box, 0.125/0.625 bounds, rail support rules.
export const isRailBlock2 = (b) => b >= POWERED_RAIL && b <= ACTIVATOR_RAIL;
// Dropper (BlockDropper extends BlockDispenser, Material.rock): an opaque normal cube. Every other new block
// is not an opaque cube and not a normal cube (fence-rail-reference.json: opaque false, normalCube false).
export const NOT_OPAQUE_NEW = Object.freeze([HOPPER, BREWING_STAND, POWERED_RAIL, DETECTOR_RAIL, ACTIVATOR_RAIL]);
// World.doesBlockHaveSolidTopSurface: BlockHopper is accepted explicitly (solidTop mask 65535 for 154);
// the brewing stand and rails are not.
export const hasSolidTop2 = (b) => b === DROPPER || b === HOPPER;
// Block.getCollisionBoundingBoxFromPool is null for rails only.
export const hasCollision2 = (b) => !isRailBlock2(b);
// Render.func_147907_a shadows need renderAsNormalBlock: only the dropper does.
export const rendersAsNormalBlock2 = (b) => b === DROPPER;
// Block.lightOpacity: setLightOpacity unset; opaque dropper 255, the rest 0 (fence-rail-reference.json "facts").
export const lightOpacity3 = (b) => (b === DROPPER ? 255 : 0);
